// Combine the forecasts for all capitals into ONE report.
// The report is the file that gets stored; the description says what it is,
// and the highlights in the metadata make it easier to find.
const capitals = $('European capitals').all().map((item) => item.json);
const forecasts = $input.all().map((item) => item.json);

// Fetch forecast returns one forecast per capital, in the order they were requested.
const cities = forecasts.map((forecast, i) => {
  const d = forecast.daily;
  return {
    city: capitals[i].city,
    country: capitals[i].country,
    latitude: capitals[i].latitude,
    longitude: capitals[i].longitude,
    timezone: forecast.timezone,
    days: d.time.map((date, j) => ({
      date,
      temperature_min_c: d.temperature_2m_min[j],
      temperature_max_c: d.temperature_2m_max[j],
      precipitation_mm: d.precipitation_sum[j],
      wind_max_kmh: d.wind_speed_10m_max[j],
      weather_code: d.weather_code[j],
    })),
  };
});

const dates = cities.flatMap((c) => c.days.map((day) => day.date)).sort();
const from = dates[0];
const to = dates[dates.length - 1];

// Highlights across the whole report.
const peak = (c) => Math.max(...c.days.map((day) => day.temperature_max_c));
const low = (c) => Math.min(...c.days.map((day) => day.temperature_min_c));
const rain = (c) => Math.round(c.days.reduce((sum, day) => sum + day.precipitation_mm, 0) * 10) / 10;
const top = (score) => cities.reduce((best, c) => (score(c) > score(best) ? c : best));
const warmest = top(peak);
const coldest = top((c) => -low(c));
const wettest = top(rain);

return [
  {
    json: {
      report: {
        title: `European capitals weather forecast ${from} to ${to}`,
        source: 'Open-Meteo',
        generated_at: $now.toISO(),
        from,
        to,
        capitals: cities.length,
        cities,
      },
      description:
        `Three-day weather forecast for ${cities.length} European capitals, ${from} to ${to}, from Open-Meteo. ` +
        `One entry per capital, with the minimum and maximum temperature, precipitation and maximum wind speed for each day. ` +
        `Read the file for the values.`,
      metadata: {
        region: 'Europe',
        capitals: cities.length,
        from,
        to,
        source: 'Open-Meteo',
        warmest: { city: warmest.city, temperature_max_c: peak(warmest) },
        coldest: { city: coldest.city, temperature_min_c: low(coldest) },
        wettest: { city: wettest.city, precipitation_mm: rain(wettest) },
      },
    },
  },
];
